mapper.select:
SELECT *
FROM menus
WHERE id = #{id}
  AND store_id = #{storeId}
  AND deleted_at IS NULL

mapper.update:
UPDATE menus
SET deleted_at = NOW(),
    updated_at = NOW()
WHERE id = #{id}
  AND store_id = #{storeId}
  AND deleted_at IS NULL

mapper.select:
SELECT *
FROM menu_loss_dismissals
WHERE store_id = #{storeId}
  AND menu_id = #{menuId}

mapper.delete:
DELETE FROM menu_loss_dismissals
WHERE store_id = #{storeId}
  AND menu_id = #{menuId}
